const DATAROOM_CSS=":root{--bg:#F7FAF8;--paper:#fff;--ink:#142E29;--muted:#516660;--soft:#55667A;--line:#DCE4EA;--accent:#087B58;--accent-dark:#066748;--accent-lite:#E6F4EE;--rail:#182C35;--rail2:#203643;--green:#1E7A4F;--amber:#8A5A0E;--red:#B42335}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif}
button,input,select,textarea{font:inherit;color:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}
:focus-visible{outline:3px solid #3FA37E;outline-offset:2px}
.dr-shell{display:grid;grid-template-columns:224px minmax(0,1fr);min-height:760px;background:var(--bg)}
.dr-rail{background:var(--rail);color:#EEF3F6;padding:22px 12px;display:flex;flex-direction:column;gap:18px;min-width:0}
.dr-brand{display:flex;flex-direction:column;padding:0 10px 14px;border-bottom:1px solid #2F4753}.dr-brand strong{font-size:17px;letter-spacing:-.2px}.dr-brand span{font-size:12px;color:#BFCDD5}
.dr-nav{display:flex;flex-direction:column;gap:3px}.dr-nav button{display:flex;align-items:center;gap:10px;width:100%;border:0;border-radius:9px;background:transparent;color:#D2DDE3;padding:10px 11px;text-align:left;font-size:14px;font-weight:560;min-height:42px}.dr-nav button:hover{background:var(--rail2);color:#fff}.dr-nav button[aria-current="page"]{background:#087B58;color:#fff;font-weight:700}.dr-ico{display:flex;width:18px;height:18px;flex:none}
.dr-rail-foot{margin-top:auto;font-size:12px;color:#BFCDD5;padding:12px 10px;border-top:1px solid #2F4753;line-height:1.6}
.dr-main{min-width:0;padding:26px clamp(16px,3vw,36px) 48px;max-width:1440px;width:100%;margin:0 auto}
.dr-top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:18px}.dr-eyebrow{font-size:12px;font-weight:700;color:var(--accent);letter-spacing:.4px;margin-bottom:4px}.dr-title{margin:0;font-size:31px;line-height:1.2;letter-spacing:-.6px;font-weight:760}.dr-subtitle{margin:6px 0 0;color:var(--muted);font-size:14px;max-width:760px}.dr-top-right{display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:flex-end}
.dr-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid #C9D5DF;background:#fff;color:#1D3A33;border-radius:9px;padding:9px 14px;font-size:14px;font-weight:620;min-height:40px;white-space:nowrap}.dr-btn:hover{border-color:#8FA6BA}.dr-btn.small{min-height:34px;padding:6px 11px;font-size:13px}.dr-btn-primary{background:var(--accent);border-color:var(--accent);color:#fff}.dr-btn-primary:hover{background:var(--accent-dark);border-color:var(--accent-dark)}.dr-btn.danger{color:var(--red);border-color:#E8C3C9}
.dr-icon-btn{display:inline-flex;align-items:center;justify-content:center;border:1px solid #C9D5DF;background:#fff;color:#1D3A33;border-radius:9px;width:40px;height:40px;padding:0}.dr-icon-btn:hover{border-color:var(--accent);color:var(--accent)}
.dr-linkbtn{border:0;background:none;color:var(--accent-dark);font-weight:650;padding:0;text-decoration:underline;text-underline-offset:2px;min-height:24px;text-align:left}
.dr-pill{display:inline-flex;align-items:center;border-radius:999px;background:#EEF2F5;color:#3B4D5E;padding:3px 10px;font-size:12px;font-weight:650;white-space:nowrap}.dr-pill.blue{background:var(--accent-lite);color:#066748}.dr-pill.green{background:#E6F4EC;color:#185F3E}.dr-pill.amber{background:#FDF1DC;color:#7A4F0C}.dr-pill.red{background:#FBE8EB;color:#9B1C2E}
.dr-banner{border:1px solid #D5E3EF;background:#EEF7F2;color:#1F3D57;border-radius:10px;padding:11px 14px;margin:0 0 14px;font-size:13px}.dr-banner.ok{background:#EAF6EF;border-color:#C9E6D5;color:#185F3E}.dr-banner.bad{background:#FDF0F2;border-color:#F0C9D0;color:#8E1D2E}.dr-banner.warn{background:#FFF7E8;border-color:#F0DDB4;color:#6B460B}.dr-notice{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}
.dr-hero{background:linear-gradient(120deg,#14262A,#182C35 60%,#203643);color:#fff;border-radius:16px;padding:24px 28px;margin-bottom:16px}.dr-hero-over{font-size:12px;letter-spacing:.5px;text-transform:uppercase;color:#C3D0D8;font-weight:650}.dr-hero-sentence{font-size:25px;line-height:1.3;font-weight:700;letter-spacing:-.4px;margin:10px 0 12px;max-width:900px}
.dr-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.dr-kpi{background:#fff;border:1px solid var(--line);border-radius:13px;padding:16px 18px;min-width:0}.dr-kpi-label{font-size:13px;color:var(--muted);font-weight:620}.dr-kpi-value{font-size:28px;font-weight:760;letter-spacing:-.5px;margin:4px 0 2px;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.dr-kpi-foot{font-size:12px;color:var(--soft)}.dr-kpi.bad .dr-kpi-value{color:var(--red)}
.dr-panel{background:#fff;border:1px solid var(--line);border-radius:14px;margin-bottom:16px;min-width:0;overflow:hidden}.dr-pad{padding:20px}.dr-panel h2{margin:0;font-size:19px;letter-spacing:-.2px}.dr-panel-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:14px;flex-wrap:wrap}.dr-panel-head p{margin:3px 0 0;color:var(--muted);font-size:13px;max-width:760px}.dr-h3{font-size:15px;margin:16px 0 8px}
.dr-grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.dr-grid2>.dr-panel{margin-bottom:16px}
.dr-scroll{overflow-x:auto;max-width:100%}.dr-table{width:100%;border-collapse:collapse;min-width:640px;font-size:14px}.dr-table caption{text-align:left;font-size:13px;color:var(--muted);padding:6px 14px}.dr-table th,.dr-table td{padding:10px 14px;border-bottom:1px solid #E8EEF2;text-align:left;vertical-align:top}.dr-table thead th{background:#F7FAFC;color:#3F5264;font-size:12px;font-weight:700;white-space:nowrap}.dr-table tbody th{font-weight:620;color:#1D3A33}.dr-table tbody tr:last-child td,.dr-table tbody tr:last-child th{border-bottom:0}.dr-table.compact th,.dr-table.compact td{padding:8px 12px;font-size:13px}.dr-table .num,.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}.neg{color:var(--red)}.pos{color:var(--green)}.dr-table tr.total th,.dr-table tr.total td{font-weight:760;border-top:2px solid var(--line);background:#F7FAFC}.dr-sub{display:block;color:var(--soft);font-size:12px;font-weight:400}
.dr-actions{text-align:right;white-space:nowrap;width:1%}.dr-actions .dr-btn{margin-left:4px}.dr-list li .dr-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:4px;white-space:normal;width:auto}.dr-list li .dr-actions .dr-btn{margin:0}.dr-list li>span:first-child{min-width:0;overflow-wrap:anywhere}
.dr-btn{max-width:100%}.dr-btn.small{white-space:normal}
.dr-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 16px;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}.dr-pager{display:inline-flex;align-items:center;gap:8px}
.dr-toolbar{display:flex;gap:9px;align-items:center;min-width:0;flex-wrap:nowrap}.dr-search{flex:1 1 180px;min-width:80px;border:1px solid #C9D5DF;border-radius:9px;padding:9px 12px;min-height:40px;background:#fff}.dr-toolbar .dr-btn{flex:none}
.dr-field{display:flex;flex-direction:column;gap:5px;font-size:13px;color:#33475A;font-weight:620;min-width:0}.dr-field.inline{flex-direction:row;align-items:center;gap:8px}.dr-field.wide{grid-column:1/-1}.dr-input,.dr-textarea,.dr-field select,.dr-field input{border:1px solid #C9D5DF;border-radius:8px;padding:9px 11px;background:#fff;min-height:40px;width:100%;min-width:0;font-weight:400;color:var(--ink)}.dr-field.inline select{width:auto;max-width:320px}.dr-textarea{min-height:96px;resize:vertical}.dr-textarea.tall{min-height:180px}.dr-textarea.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px}
.dr-check{display:inline-flex;align-items:center;gap:8px;font-size:14px;min-height:40px;font-weight:400;color:var(--ink)}.dr-check input{width:18px;height:18px;min-height:0;accent-color:var(--accent);flex:none}.dr-checks{display:flex;flex-direction:column;gap:2px;margin:6px 0 10px}
.dr-row{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:12px}.dr-row.end{justify-content:flex-end}.dr-row.top0{margin-top:0}
.dr-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.dr-form .dr-row{grid-column:1/-1;margin-top:0}
.dr-list{list-style:none;margin:0;padding:0}.dr-list li{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid #EEF2F5;font-size:14px}.dr-list li:last-child{border-bottom:0}.dr-list.plain li{display:block}.dr-list.pad{padding:0 20px 12px}
.dr-kv{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #EEF2F5;font-size:14px}.dr-kv span{color:var(--muted)}.dr-kv strong{text-align:right;overflow-wrap:anywhere}
.dr-empty{text-align:center;border:1px dashed #C9D5DF;border-radius:12px;padding:28px;color:var(--muted);background:#FBFDFE}.dr-empty strong{display:block;color:var(--ink);font-size:16px;margin-bottom:4px}.dr-none{padding:18px 20px;color:var(--muted);font-size:14px}.dr-muted{color:var(--muted);font-size:13px}
.dr-overlay{position:fixed;inset:0;z-index:30;background:#0E1C2A66;display:flex;justify-content:flex-end;align-items:flex-start;overflow-y:auto}.dr-overlay.center{justify-content:center;align-items:center;padding:16px}
.dr-drawer{width:min(600px,100%);min-height:100%;background:#fff;display:flex;flex-direction:column;box-shadow:-16px 0 40px #0E1C2A33}.dr-drawer.wide{width:min(820px,100%)}.dr-drawer-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;padding:18px 22px;border-bottom:1px solid var(--line)}.dr-drawer-head h2{margin:0;font-size:21px}.dr-drawer-form{display:flex;flex-direction:column;flex:1}.dr-drawer-body{flex:1;padding:18px 22px;display:flex;flex-direction:column;gap:12px}.dr-drawer-foot{display:flex;justify-content:flex-end;align-items:center;gap:8px;padding:14px 22px;border-top:1px solid var(--line);flex-wrap:wrap}.dr-drawer-foot .dr-muted{margin-right:auto}
.dr-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.dr-foot{font-size:12px;color:var(--soft);margin-top:20px}
.dr-picker{display:flex;flex-wrap:wrap;gap:10px 16px;align-items:flex-end;background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px 16px;margin-bottom:16px}.dr-picker .dr-field{flex:1 1 260px}.dr-picker-meta{display:flex;flex-wrap:wrap;gap:6px;align-items:center;min-height:40px}
.dr-stepper{list-style:none;display:flex;gap:6px;margin:0 0 14px;padding:0;overflow-x:auto}.dr-step{flex:1 0 96px;border-top:4px solid #D5DEE6;padding:8px 6px 0;font-size:12px;color:var(--muted);min-width:0}.dr-step b{display:block;font-size:13px;color:#3F5264}.dr-step.done{border-top-color:#7FA8CE}.dr-step.now{border-top-color:var(--accent)}.dr-step.now b{color:var(--accent-dark)}.dr-step.skip{opacity:.55}
.dr-next{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;background:var(--accent-lite);border:1px solid #BFE0D1;border-radius:10px;padding:12px 14px;font-size:14px}
.dr-chips{display:flex;flex-wrap:wrap;gap:5px}
.dr-thread{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}.dr-msg{border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:14px;max-width:92%;overflow-wrap:anywhere;white-space:pre-wrap}.dr-msg.them{background:#F7FAFC;align-self:flex-start}.dr-msg.us{background:var(--accent-lite);border-color:#BFE0D1;align-self:flex-end}.dr-msg.clar{background:#FFF9EC;border-color:#F0DDB4;max-width:100%}.dr-msg-meta{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:center;font-size:12px;color:var(--soft);margin-bottom:4px;white-space:normal}
.dr-mail{border:1px solid var(--line);border-radius:10px;margin-top:10px;overflow:hidden}.dr-mail-head{background:#F7FAFC;padding:8px 12px;font-size:13px;display:flex;flex-wrap:wrap;gap:4px 14px;border-bottom:1px solid var(--line)}.dr-mail pre{margin:0;padding:12px;font:13px/1.5 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;color:#1D3A33}
.dr-report{white-space:pre-wrap;font-size:14px;color:#22313F;background:#FAFCFE;border:1px solid var(--line);border-radius:10px;padding:14px 16px;overflow-wrap:anywhere}
.dr-dev{display:block;font-size:12px}.dr-flag{display:inline-block;margin-top:2px;font-size:12px;color:#7A4F0C;background:#FDF1DC;border-radius:6px;padding:1px 6px;white-space:normal}

.dr-supplier{border:1px solid var(--line);border-radius:12px;padding:14px 16px;margin:0 20px 12px}.dr-supplier-head{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:6px}.dr-supplier h3{margin:0;font-size:16px}
.dr-field small{font-weight:400}
.dr-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
@media(max-width:1100px){.dr-shell{grid-template-columns:64px minmax(0,1fr)}.dr-brand span,.dr-nav-label,.dr-rail-foot{display:none}.dr-brand{padding:0 0 12px;align-items:center}.dr-brand strong{font-size:11px;text-align:center}.dr-nav button{justify-content:center;padding:10px 6px}.dr-grid2{grid-template-columns:minmax(0,1fr)}.dr-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:720px){.dr-shell{display:block}.dr-rail{padding:10px 12px;gap:8px;position:static}.dr-brand{display:none}.dr-nav{flex-direction:row;overflow-x:auto;gap:4px}.dr-nav button{width:auto;min-width:44px;justify-content:center;padding:10px}.dr-main{padding:18px 16px 40px}.dr-top{flex-direction:column}.dr-top-right{justify-content:flex-start}.dr-title{font-size:26px}.dr-hero{padding:20px}.dr-hero-sentence{font-size:20px}.dr-kpis{grid-template-columns:minmax(0,1fr)}.dr-kpi-value{font-size:24px}.dr-pair,.dr-form{grid-template-columns:minmax(0,1fr)}.dr-pad{padding:16px}.dr-hide-xs{display:none}.dr-field.inline{flex-direction:column;align-items:stretch}.dr-field.inline select{width:100%;max-width:none}.dr-actions .dr-btn{margin:2px 0 2px 4px}.dr-supplier{margin:0 12px 12px}.dr-msg{max-width:100%}.dr-drawer-head,.dr-drawer-body,.dr-drawer-foot{padding-left:16px;padding-right:16px}}

/* Data Room additions */
.dr-picker{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end;margin:0 0 16px}.dr-picker .dr-field{min-width:260px;margin:0}.dr-picker-meta{display:flex;flex-wrap:wrap;gap:6px;padding-bottom:8px}
.dr-steps{list-style:none;margin:0 0 12px;padding:0;display:flex;flex-wrap:wrap;gap:8px}.dr-steps li{padding:6px 12px;border:1px solid var(--line);border-radius:999px;font-size:13px;color:var(--muted);background:#fff}.dr-steps li.done{border-color:#BFE0D1;background:#E6F4EE;color:#185F3E;font-weight:600}.dr-steps li.done::before{content:"✓ "}
.dr-sec{margin-top:18px}.dr-sec-head{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between;margin-bottom:8px}.dr-sec-head h3{display:flex;align-items:center;gap:10px;margin:0;font-size:16px}
.dr-num{display:inline-flex;min-width:34px;justify-content:center;padding:2px 8px;border-radius:8px;background:#E6F4EE;color:#185F3E;font-variant-numeric:tabular-nums;font-size:13px;font-weight:700}
.dr-heat{background:#E6F4EE;color:#185F3E;font-weight:700}
.dr-mail{border:1px solid var(--line);border-radius:12px;margin:0 0 12px;background:#fff;overflow:hidden}.dr-mail-head{display:flex;gap:8px;align-items:center;justify-content:space-between;padding:10px 14px;background:#F7FAF8;border-bottom:1px solid var(--line)}.dr-mail-subject{padding:10px 14px 0;font-weight:700}.dr-mail-body{margin:0;padding:8px 14px 14px;white-space:pre-wrap;word-break:break-word;font:13px/1.55 Inter,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;color:var(--ink)}
.dr-quote{margin:0 0 14px;padding:10px 14px;border-left:4px solid #087B58;background:#F7FAF8;border-radius:8px;white-space:pre-wrap}
.dr-preview{margin:10px 0 0;padding-left:18px}.dr-preview li{margin:4px 0}.dr-preview ul{margin:4px 0 8px;padding-left:18px}
.dr-fieldset{border:1px solid var(--line);border-radius:10px;padding:10px 14px;margin:0 0 14px;display:flex;flex-direction:column;gap:6px}.dr-fieldset legend{font-weight:700;padding:0 6px}
.dr-integ{margin-top:18px}.dr-pre{white-space:pre-wrap}.dr-field.grow{flex:1 1 260px}
@media (max-width:720px){.dr-picker .dr-field{min-width:0;width:100%}.dr-sec-head{align-items:flex-start}}
.dr-link{border:0;background:none;padding:0;color:#066748;font-weight:650;text-align:left;text-decoration:underline;text-underline-offset:2px;cursor:pointer;font-size:inherit;min-height:24px}.dr-link:hover{color:#142E29}
.dr-list.plain li{display:block}
